using System.Net.Http;
using System.Text.Json;
using System.Text.RegularExpressions;
namespace LeoLauncher;
sealed record QQPlaylistData(string Id,string Name,MusicSong[] Songs,int Total);
static class QQPlaylists
{
    static readonly HttpClient http=new(new HttpClientHandler{UseCookies=false,AllowAutoRedirect=false}){Timeout=TimeSpan.FromSeconds(18)};
    public static bool ValidId(string? id)=>id is {Length:>0 and <=18}&&id.All(char.IsAsciiDigit);
    public static string? ExtractId(string text){text=text.Trim();if(ValidId(text))return text;if(!Uri.TryCreate(text,UriKind.Absolute,out var u)||u.Scheme!="https"||u.Host is not("y.qq.com" or "i.y.qq.com" or "c.y.qq.com"))return null;var m=Regex.Match(u.AbsolutePath,@"^/n/ryqq/playlist/(\d{1,18})/?$");if(m.Success)return m.Groups[1].Value;if(!u.AbsolutePath.Contains("taoge",StringComparison.OrdinalIgnoreCase)&&!u.AbsolutePath.Contains("playlist",StringComparison.OrdinalIgnoreCase))return null;foreach(var part in u.Query.TrimStart('?').Split('&')){var pair=part.Split('=',2);if(pair.Length==2&&pair[0] is "id" or "disstid"&&ValidId(pair[1]))return pair[1];}return null;}
    public static QQPlaylistData Parse(string json,string id){using var document=JsonDocument.Parse(json);var r=document.RootElement;if(r.TryGetProperty("code",out var code)&&code.GetInt32()!=0)throw new IOException("歌单不可公开读取，请检查分享权限");if(!r.TryGetProperty("cdlist",out var lists)||lists.ValueKind!=JsonValueKind.Array||lists.GetArrayLength()==0)throw new IOException("没有找到公开歌单");var p=lists[0];if(Get(p,"disstid")!=id)throw new IOException("返回的歌单编号不匹配，已保留缓存");if(!p.TryGetProperty("songlist",out var tracks)||tracks.ValueKind!=JsonValueKind.Array)throw new IOException("歌曲列表不完整，已保留缓存");var songs=tracks.EnumerateArray().Select(s=>{bool modern=s.TryGetProperty("mid",out _);string artist=s.TryGetProperty("singer",out var singers)&&singers.ValueKind==JsonValueKind.Array?string.Join(" / ",singers.EnumerateArray().Select(x=>Get(x,"name"))):"";string album=modern&&s.TryGetProperty("album",out var a)?Get(a,"name"):Get(s,"albumname");return new MusicSong(Get(s,modern?"id":"songid"),Get(s,modern?"mid":"songmid"),Get(s,modern?"name":"songname"),artist,album);}).Where(QQMusic.Valid).DistinctBy(s=>s.Id).Take(200).ToArray();int total=p.TryGetProperty("total_song_num",out var n)&&n.TryGetInt32(out var count)?count:p.TryGetProperty("songnum",out n)&&n.TryGetInt32(out count)?count:tracks.GetArrayLength();if(total>0&&songs.Length==0||tracks.GetArrayLength()>0&&songs.Length==0)throw new IOException("歌单曲目暂未完整返回，已保留缓存");if(songs.Length<Math.Min(total,200))throw new IOException("只返回部分曲目，暂不覆盖本地歌单");string name=Get(p,"dissname");if(name.Length==0)throw new IOException("歌单名称缺失");return new(id,name,songs,total);}
    static string Get(JsonElement e,string name)=>e.TryGetProperty(name,out var v)?System.Net.WebUtility.HtmlDecode(v.ValueKind==JsonValueKind.String?v.GetString()??"":v.ToString()):"";
    public static async Task<QQPlaylistData> Fetch(string id,CancellationToken token){if(!ValidId(id))throw new ArgumentException("歌单编号无效");Exception? failure=null;foreach(var host in new[]{"https://c.y.qq.com/qzone/fcg-bin/","https://i.y.qq.com/qzone-music/"}){token.ThrowIfCancellationRequested();try{string url=host+"fcg_ucc_getcdinfo_byids_cp.fcg?type=1&json=1&utf8=1&onlysong=0&disstid="+id+"&format=json&platform=yqq.json&new_format=1&song_begin=0&song_num=200";using var request=new HttpRequestMessage(HttpMethod.Get,url);request.Headers.Referrer=new Uri("https://y.qq.com/");request.Headers.UserAgent.ParseAdd("Mozilla/5.0");using var response=await http.SendAsync(request,HttpCompletionOption.ResponseHeadersRead,token);response.EnsureSuccessStatusCode();using var stream=await response.Content.ReadAsStreamAsync(token);using var memory=new MemoryStream();byte[] buffer=new byte[16384];int read;while((read=await stream.ReadAsync(buffer,token))>0){if(memory.Length+read>8_000_000)throw new IOException("歌单响应过大");memory.Write(buffer,0,read);}return Parse(System.Text.Encoding.UTF8.GetString(memory.ToArray()),id);}catch(Exception e)when(e is HttpRequestException or IOException or JsonException or TaskCanceledException){token.ThrowIfCancellationRequested();failure=e;}}throw new IOException("QQ歌单同步失败，已保留上次成功缓存。"+failure?.Message);}
}
